import { useState } from 'react';
import { getSourceCodenames } from '../data/sources';
import { airportGroups } from '../data/airportGroups';

export default function useNormalFlightSearch() {
  const [flightData, setFlightData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [selectedDateRange, setSelectedDateRange] = useState(null);
  const [selectedFlights, setSelectedFlights] = useState(null);
  const [pricingData, setPricingData] = useState(null);
  const [currentRoute, setCurrentRoute] = useState([]);

  const expandAirportGroup = (airport) => {
    return airportGroups[airport]?.split('/') || [airport];
  };

  const generateRoutePermutations = (segments) => {
    // Expand each segment into its possible airports
    const expandedSegments = segments.map(segment => {
      if (airportGroups[segment]) {
        return expandAirportGroup(segment).sort();
      }
      return [segment];
    });

    // Get all possible combinations between first and last segments
    const firstAirports = expandedSegments[0];
    const lastAirports = expandedSegments[expandedSegments.length - 1];

    // Generate all possible routes between first and last airports
    const routes = [];
    firstAirports.forEach(from => {
      lastAirports.forEach(to => {
        routes.push(`${from}-${to}`);
      });
    });

    // Sort routes alphabetically
    return routes.sort();
  };

  const processFlightData = (data) => {
    // Group flights by date and route
    const flightsByDate = {};

    console.log('Raw API response:', data);

    // Generate all possible routes we want to include
    const validRoutes = generateRoutePermutations(currentRoute);
    console.log('Valid routes to include:', validRoutes);

    data.forEach(flight => {
      const date = flight.date;
      const route = `${flight.originAirport}-${flight.destinationAirport}`;

      console.log('Processing flight:', { date, route });

      // Simply check if this route is in our valid routes list
      if (validRoutes.includes(route)) {
        if (!flightsByDate[date]) {
          flightsByDate[date] = {};
        }

        flightsByDate[date][route] = {
          classes: {
            Y: { available: flight.YAvailable, direct: flight.YDirect, airlines: flight.YAirlines },
            W: { available: flight.WAvailable, direct: flight.WDirect, airlines: flight.WAirlines },
            J: { available: flight.JAvailable, direct: flight.JDirect, airlines: flight.JAirlines },
            F: { available: flight.FAvailable, direct: flight.FDirect, airlines: flight.FAirlines }
          }
        };
      }
    });

    console.log('Processed flight data:', flightsByDate);
    return flightsByDate;
  };

  const handleSearch = async (searchParams, setExternalFlightData) => {
    const { path, sourcesExcluded, apiKey, dateRange } = searchParams;

    console.log('Search params:', { path, sourcesExcluded, dateRange });

    // Reset errors
    setErrors({});

    // Validate mandatory fields
    if (!path) {
      setErrors({ path: 'Path is required' });
      return;
    }

    // Split path into segments by hyphen only
    const segments = path.split('-');
    if (segments.length < 2) {
      setErrors({ path: 'Invalid path format' });
      return;
    }

    // Update current route segments
    setCurrentRoute(segments);
    console.log('Current route segments:', segments);

    // Get all available source codenames and exclude the ones selected by user
    const allSources = getSourceCodenames();
    const includedSources = allSources.filter(source => !sourcesExcluded.includes(source));

    setIsLoading(true);
    setFlightData({}); // Clear existing data before new search
    try {
      // Generate route permutations first
      const routePermutations = generateRoutePermutations(segments);
      console.log('Route permutations:', routePermutations);

      // Make parallel requests for each route permutation
      const responses = await Promise.all(
        routePermutations.map(routeId =>
          fetch('https://backend-284998006367.us-central1.run.app/api/availability-v2', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Partner-Authorization': apiKey
            },
            body: JSON.stringify({
              routeId,
              startDate: dateRange[0],
              endDate: dateRange[1],
              sources: includedSources.join(',')
            })
          })
        )
      );

      // Check if any request failed
      if (responses.some(response => !response.ok)) {
        throw new Error('Search failed');
      }

      // Combine all responses
      const allData = await Promise.all(responses.map(response => response.json()));
      const combinedData = allData.flat();
      console.log('Combined API response:', combinedData);

      const processedData = processFlightData(combinedData);
      console.log('Processed data:', processedData);

      const flightDataObj = {
        routes: routePermutations,
        data: processedData
      };
      console.log('Final flight data object:', flightDataObj);

      setFlightData(flightDataObj);
      if (setExternalFlightData) {
        setExternalFlightData(flightDataObj);
      }
      setSelectedDateRange(dateRange);
    } catch (error) {
      console.error('Search failed:', error);
      setErrors({ general: 'Search failed. Please try again.' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleDateRangeSelect = (dateRange) => {
    setSelectedDateRange(dateRange);
  };

  const handleFlightSelect = (flights, pricing) => {
    setSelectedFlights(flights);
    setPricingData(pricing);
  };

  return {
    flightData,
    isLoading,
    handleSearch,
    errors,
    selectedDateRange,
    handleDateRangeSelect,
    selectedFlights,
    handleFlightSelect,
    pricingData
  };
}
